{
  "story": "Watch a dataset split into two child nodes. Compute Gini impurity for each side and find the information gain.",
  "aha": {
    "stateId": "split",
    "observation": "Information gain measures the drop in impurity achieved by the split."
  },
  "layout": {
    "preset": "card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "variant.states[inputs.stepIndex].active",
        "regions": "variant.regions"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states[inputs.stepIndex].why",
        "target": "variant.states[inputs.stepIndex].calloutRegion",
        "text": "variant.states[inputs.stepIndex].sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states[inputs.stepIndex].readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Step",
      "options": ["Parent node", "Left child", "Right child", "Information gain"]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Gini Split",
        "regions": [
          {
            "id": "parent",
            "label": "Parent Node",
            "kind": "node",
            "values": ["6 Yes", "6 No"]
          },
          {
            "id": "left",
            "label": "Left Child",
            "kind": "node",
            "values": ["5 Yes", "1 No"]
          },
          {
            "id": "right",
            "label": "Right Child",
            "kind": "node",
            "values": ["1 Yes", "5 No"]
          }
        ],
        "states": [
          {
            "id": "parent_state",
            "label": "Parent",
            "short": "Parent",
            "sentence": "The parent node contains 6 positive and 6 negative samples.",
            "why": "Base impurity is 1 - (0.5^2 + 0.5^2) = 0.500.",
            "active": ["parent"],
            "calloutRegion": "parent",
            "readouts": [
              {
                "id": "gini_p",
                "label": "Parent Gini",
                "value": "0.500"
              }
            ]
          },
          {
            "id": "left_state",
            "label": "Left Child",
            "short": "Left",
            "sentence": "The left child node contains 5 positive and 1 negative sample.",
            "why": "Left impurity is 1 - ((5/6)^2 + (1/6)^2) = 0.278.",
            "active": ["left"],
            "calloutRegion": "left",
            "readouts": [
              {
                "id": "gini_l",
                "label": "Left Gini",
                "value": "0.278"
              }
            ]
          },
          {
            "id": "right_state",
            "label": "Right Child",
            "short": "Right",
            "sentence": "The right child node contains 1 positive and 5 negative samples.",
            "why": "Right impurity is 1 - ((1/6)^2 + (5/6)^2) = 0.278.",
            "active": ["right"],
            "calloutRegion": "right",
            "readouts": [
              {
                "id": "gini_r",
                "label": "Right Gini",
                "value": "0.278"
              }
            ]
          },
          {
            "id": "split",
            "label": "Information Gain",
            "short": "Gain",
            "sentence": "Information gain subtracts the weighted child impurity from the parent impurity.",
            "why": "Gain = 0.500 - ((6/12)*0.278 + (6/12)*0.278) = 0.222.",
            "active": ["left", "right"],
            "calloutRegion": "left",
            "readouts": [
              {
                "id": "gain",
                "label": "Info Gain",
                "value": "0.222"
              }
            ]
          }
        ]
      }
    ]
  }
}
